INSERT INTO resources (scope_id,kind,schema_version,name,config,status) SELECT p.scope_id,'Skill',2,'Elasticsearch 健康诊断',jsonb_build_object('summary','Elasticsearch 集群、节点、索引、分片和配置的只读诊断。','owner','OpsKeeper builtin'),'active' FROM platforms p WHERE p.code='default' ON CONFLICT (scope_id,kind,lower(name)) WHERE deleted_at IS NULL DO NOTHING;
INSERT INTO skill_versions (skill_resource_id,version,manifest,input_schema,output_schema,tools,risk_level,status,published_at) SELECT r.id,COALESCE((SELECT max(v.version)+1 FROM skill_versions v WHERE v.skill_resource_id=r.id),1),jsonb_build_object('name',r.name,'description',r.config->>'summary','instruction','调用 Elasticsearch 固定只读工具；不要请求管理操作。','target_kinds','["Elasticsearch"]'::jsonb),'{}'::jsonb,'{}'::jsonb,'[{"name":"elasticsearch_health"},{"name":"elasticsearch_cluster_info"},{"name":"elasticsearch_nodes"},{"name":"elasticsearch_indices"},{"name":"elasticsearch_shards"},{"name":"elasticsearch_settings"},{"name":"elasticsearch_index_mapping"}]'::jsonb,'read_only','published',now() FROM resources r WHERE r.kind='Skill' AND r.name='Elasticsearch 健康诊断' AND r.config->>'owner'='OpsKeeper builtin';
